style.css:
@-moz-document domain("youtube.com") {
/* Genel gövde ve temel container'lar */
  body, ytd-app, #background, html {
    background-color: #000 !important;
    background-image: none !important;
    color: #fff !important;
  }

  /* Üst bar ve sol menü */
  ytd-masthead, tp-yt-app-drawer, ytd-mini-guide-renderer, ytd-guide-renderer {
    background-color: #000 !important;
    color: #fff !important;
  }

  /* Sayfa içi ana bloklar */
  ytd-page-manager, ytd-watch-flexy, #columns, #secondary {
    background-color: #000 !important;
    color: #fff !important;
  }

  /* Kartlar ve kutular */
  ytd-rich-grid-media, ytd-video-renderer, ytd-thumbnail, ytd-playlist-renderer {
    background-color: #111 !important;
    color: #fff !important;
    border-radius: 8px !important;
  }

  /* Hover efekti yumuşak koyu gri */
  ytd-rich-grid-media:hover {
    background-color: #1a1a1a !important;
  }

  /* Yazı renkleri */
  yt-formatted-string, h1, h2, h3, span, div, a {
    color: #fff !important;
  }

  /* Butonlar & inputlar */
  paper-button, yt-icon-button, input, button {
    background-color: #111 !important;
    color: #fff !important;
    border: none !important;
  }

  /* Scrollbar siyah temalı */
  ::-webkit-scrollbar {
    width: 10px;
    background-color: #000;
  }

  ::-webkit-scrollbar-thumb {
    background-color: #333;
    border-radius: 5px;
  }

  /* Video başlığı ve kanal adı daha belirgin */
  #video-title, #channel-name {
    color: #fff !important;
    font-weight: bold !important;
  }
}
